import type { Argv, ArgumentsCamelCase } from 'yargs'
import { cwd } from 'process'
import * as fs from 'fs'
import { validateWorkingDir } from '../../util'
import { withProfiling } from '../../util/profiler'
import { logger } from '../../logger'
import { createTelemetryClient } from '../../telemetry'
import { Orchestrator, Project } from '@servicenow/sdk-api'
import { NowConfig } from '@servicenow/sdk-build-core'

interface Arguments {
    source: string
    frozenKeys: boolean
    errorOnConflict: boolean
    skipClean: boolean
    emitDictionary: boolean
    ids: string[] | undefined
    profile: boolean
}

export function builder(yargs: Argv) {
    return yargs
        .positional('source', {
            describe: `Path to the directory that contains package.json configuration`,
            default: cwd(),
            type: 'string',
        })
        .option('frozenKeys', {
            describe: 'Validate that Keys/SysIds are up to date for CI build',
            default: false,
            type: 'boolean',
        })
        .option('errorOnConflict', {
            describe:
                'Treat sys_id conflicts between Fluent and XML as errors instead of warnings (Fluent-to-Fluent conflicts are always errors)',
            default: false,
            type: 'boolean',
        })
        .option('ids', {
            describe: `Array of sysIds of records to build`,
            type: 'array',
            string: true,
            hidden: true,
        })
        .option('skipClean', {
            describe: 'Skip cleaning build output directories before building',
            type: 'boolean',
            default: false,
        })
        .option('emitDictionary', {
            describe: 'Generate sys_dictionary and sys_db_object update records alongside bootstrap XML',
            type: 'boolean',
            hidden: true,
            default: true,
        })
        .option('profile', {
            describe: 'Profile build and output a .cpuprofile file',
            type: 'boolean',
            default: false,
            hidden: true,
        })
}

export async function handler(args: ArgumentsCamelCase<Arguments>): Promise<void> {
    await withProfiling(args.profile, 'build', fs, async () => {
        logger.info(`Initiating the build process ${args.frozenKeys ? 'with keys validation' : ''}...`)

        const telemetryClient = createTelemetryClient(__dirname)

        logger.info(`Building project from ${args.source}...`)

        try {
            const workingDir = validateWorkingDir(args.source)

            const config = NowConfig.parseFromDirectory(workingDir, fs, logger)

            config.emitDictionary = args.emitDictionary

            const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger, telemetryClient })

            const orchestrator = new Orchestrator(project)

            const output = await orchestrator.build({
                frozenKeys: args.frozenKeys,
                sysIds: args.ids,
                errorOnConflict: args.errorOnConflict,
                skipClean: args.skipClean,
            })

            if (!output.success) {
                logger.error('Build failed due to errors')
                process.exitCode = 1 // set exit code to 1 to indicate failure for CI
                return
            }

            logger.debug(`Build output\n${output.files.map((f) => f.path).join('\n')}`)
            logger.info('Build completed successfully')
        } catch (error) {
            logger.error('Build failed:', error)

            process.exitCode = 1 // set exit code to 1 to indicate failure for CI
        }
    })
}
